mapper.select:
SELECT COUNT(1)
FROM sys_rbac_user_role_rel urr
         JOIN sys_rbac_role r ON r.id = urr.role_id AND r.delete_time IS NULL
WHERE urr.user_id = #{userId}
  AND r.code = #{superAdminCode}
  AND r.status = #{activeStatus}

SELECT DISTINCT p.http_path
FROM sys_rbac_user_role_rel urr
         JOIN sys_rbac_role r ON r.id = urr.role_id AND r.status = #{activeStatus} AND r.delete_time IS NULL
         JOIN sys_rbac_role_group_rel rgr ON rgr.role_id = r.id
         JOIN sys_rbac_perm_group g ON g.id = rgr.group_id AND g.status = #{activeStatus} AND g.delete_time IS NULL
         JOIN sys_rbac_group_perm_rel gpr ON gpr.group_id = g.id
         JOIN sys_rbac_perm p ON p.id = gpr.perm_id AND p.status = #{activeStatus}
    AND p.type = #{apiType} AND p.delete_time IS NULL
WHERE urr.user_id = #{userId}
  AND p.http_method = #{method}

SELECT *
FROM sys_rbac_perm
WHERE type = #{menuType}
  AND status = #{activeStatus}
  AND delete_time IS NULL
ORDER BY id ASC

SELECT DISTINCT urr.user_id
FROM sys_rbac_user_role_rel urr
         JOIN sys_rbac_role r ON r.id = urr.role_id AND r.delete_time IS NULL
WHERE r.code = #{superAdminCode}
  AND r.status = #{activeStatus}
